BEGIN
 FOR s IN SELECT value FROM jsonb_array_elements($bank$[{"key":"systems-lab","order":2,"questions":[{"text":"Khảo sát nghiệp vụ nhằm mục đích chính gì?","options":["Quy trình dự kiến sau cải tiến","Hiểu quy trình hiện tại và nhu cầu nghiệp vụ","Danh sách yêu cầu được ghi nhận có nguồn","Thao tác và ngoại lệ không được mô tả"],"correct":1},{"text":"Đầu ra quan trọng của buổi phỏng vấn người dùng là gì?","options":["Những chức năng trong và ngoài dự án","Thời gian phản hồi dưới hai giây","Danh sách yêu cầu được ghi nhận có nguồn","Người hoặc nhóm có liên quan đến hệ thống"],"correct":2},{"text":"Ai được gọi là stakeholder?","options":["Thao tác và ngoại lệ không được mô tả","Cách nghiệp vụ đang vận hành","Làm rõ và thống nhất với bên liên quan","Người hoặc nhóm có liên quan đến hệ thống"],"correct":3},{"text":"Quan sát nghiệp vụ thực tế giúp phát hiện điều gì?","options":["Thao tác và ngoại lệ không được mô tả","Những chức năng trong và ngoài dự án","Quy trình dự kiến sau cải tiến","Tránh hiểu sai nhu cầu của người dùng"],"correct":0},{"text":"Phạm vi dự án cần xác định điều gì?","options":["Hiểu quy trình hiện tại và nhu cầu nghiệp vụ","Những chức năng trong và ngoài dự án","Cách nghiệp vụ đang vận hành","Thời gian phản hồi dưới hai giây"],"correct":1},{"text":"Quy trình AS-IS thể hiện điều gì?","options":["Làm rõ và thống nhất với bên liên quan","Danh sách yêu cầu được ghi nhận có nguồn","Cách nghiệp vụ đang vận hành","Quy trình dự kiến sau cải tiến"],"correct":2},{"text":"Quy trình TO-BE thể hiện điều gì?","options":["Thời gian phản hồi dưới hai giây","Tránh hiểu sai nhu cầu của người dùng","Người hoặc nhóm có liên quan đến hệ thống","Quy trình dự kiến sau cải tiến"],"correct":3},{"text":"Yêu cầu phi chức năng là ví dụ nào?","options":["Thời gian phản hồi dưới hai giây","Làm rõ và thống nhất với bên liên quan","Hiểu quy trình hiện tại và nhu cầu nghiệp vụ","Thao tác và ngoại lệ không được mô tả"],"correct":0},{"text":"Khi hai bộ phận đưa yêu cầu mâu thuẫn, cần làm gì?","options":["Những chức năng trong và ngoài dự án","Làm rõ và thống nhất với bên liên quan","Tránh hiểu sai nhu cầu của người dùng","Danh sách yêu cầu được ghi nhận có nguồn"],"correct":1},{"text":"Vì sao cần xác nhận biên bản khảo sát?","options":["Người hoặc nhóm có liên quan đến hệ thống","Cách nghiệp vụ đang vận hành","Tránh hiểu sai nhu cầu của người dùng","Hiểu quy trình hiện tại và nhu cầu nghiệp vụ"],"correct":2}]},{"key":"systems-lab","order":3,"questions":[{"text":"Đối tượng nghiệp vụ thường biểu diễn điều gì?","options":["Thực thể có ý nghĩa trong miền bài toán","Thứ tự thông điệp theo thời gian","Bên gọi chờ lời gọi hoàn tất","Kết quả phản hồi của thao tác"],"correct":0},{"text":"Sơ đồ tuần tự nhấn mạnh khía cạnh nào?","options":["Các nhánh xử lý theo điều kiện","Thứ tự thông điệp theo thời gian","Sự tồn tại của đối tượng theo thời gian","Liên kết tương tác giữa các đối tượng"],"correct":1},{"text":"Lifeline trong sequence diagram biểu diễn gì?","options":["Vai trò tương tác với hệ thống","Tương tác được lặp theo điều kiện","Sự tồn tại của đối tượng theo thời gian","Bên gọi chờ lời gọi hoàn tất"],"correct":2},{"text":"Thông điệp đồng bộ thường yêu cầu điều gì?","options":["Liên kết tương tác giữa các đối tượng","Kết quả phản hồi của thao tác","Đảm bảo luồng tương tác phù hợp nghiệp vụ","Bên gọi chờ lời gọi hoàn tất"],"correct":3},{"text":"Sơ đồ cộng tác chú trọng điều gì?","options":["Liên kết tương tác giữa các đối tượng","Vai trò tương tác với hệ thống","Các nhánh xử lý theo điều kiện","Thực thể có ý nghĩa trong miền bài toán"],"correct":0},{"text":"Actor trong phân tích nghiệp vụ là gì?","options":["Thứ tự thông điệp theo thời gian","Vai trò tương tác với hệ thống","Kết quả phản hồi của thao tác","Tương tác được lặp theo điều kiện"],"correct":1},{"text":"Thông điệp trả về trong sơ đồ tuần tự là gì?","options":["Đảm bảo luồng tương tác phù hợp nghiệp vụ","Sự tồn tại của đối tượng theo thời gian","Kết quả phản hồi của thao tác","Các nhánh xử lý theo điều kiện"],"correct":2},{"text":"Alternative fragment dùng để mô tả gì?","options":["Tương tác được lặp theo điều kiện","Thực thể có ý nghĩa trong miền bài toán","Bên gọi chờ lời gọi hoàn tất","Các nhánh xử lý theo điều kiện"],"correct":3},{"text":"Loop fragment dùng khi nào?","options":["Tương tác được lặp theo điều kiện","Đảm bảo luồng tương tác phù hợp nghiệp vụ","Thứ tự thông điệp theo thời gian","Liên kết tương tác giữa các đối tượng"],"correct":0},{"text":"Vì sao đối chiếu mô hình với kịch bản thực?","options":["Vai trò tương tác với hệ thống","Đảm bảo luồng tương tác phù hợp nghiệp vụ","Thực thể có ý nghĩa trong miền bài toán","Sự tồn tại của đối tượng theo thời gian"],"correct":1}]},{"key":"systems-lab","order":4,"questions":[{"text":"Use case mô tả điều gì?","options":["Vai trò bên ngoài tương tác với hệ thống","Trạng thái sau khi use case kết thúc","Tình huống lỗi hoặc ngoại lệ","Mục tiêu tương tác của tác nhân với hệ thống"],"correct":3},{"text":"Actor là gì trong use case?","options":["Vai trò bên ngoài tương tác với hệ thống","Điều kiện cần đúng trước khi thực hiện","Chuỗi bước thành công thông thường","Tái sử dụng hành vi bắt buộc dùng chung"],"correct":0},{"text":"Precondition của use case là gì?","options":["Bổ sung hành vi tùy theo điều kiện","Điều kiện cần đúng trước khi thực hiện","Trạng thái sau khi use case kết thúc","Nhánh xử lý hợp lệ khác luồng chính"],"correct":1},{"text":"Postcondition mô tả điều gì?","options":["Tình huống lỗi hoặc ngoại lệ","Các chức năng thuộc phạm vi hệ thống","Trạng thái sau khi use case kết thúc","Chuỗi bước thành công thông thường"],"correct":2},{"text":"Main flow thể hiện điều gì?","options":["Nhánh xử lý hợp lệ khác luồng chính","Tái sử dụng hành vi bắt buộc dùng chung","Mục tiêu tương tác của tác nhân với hệ thống","Chuỗi bước thành công thông thường"],"correct":3},{"text":"Alternative flow thể hiện điều gì?","options":["Nhánh xử lý hợp lệ khác luồng chính","Tình huống lỗi hoặc ngoại lệ","Bổ sung hành vi tùy theo điều kiện","Vai trò bên ngoài tương tác với hệ thống"],"correct":0},{"text":"Exception flow thể hiện điều gì?","options":["Điều kiện cần đúng trước khi thực hiện","Tình huống lỗi hoặc ngoại lệ","Tái sử dụng hành vi bắt buộc dùng chung","Các chức năng thuộc phạm vi hệ thống"],"correct":1},{"text":"Quan hệ include dùng để làm gì?","options":["Mục tiêu tương tác của tác nhân với hệ thống","Trạng thái sau khi use case kết thúc","Tái sử dụng hành vi bắt buộc dùng chung","Bổ sung hành vi tùy theo điều kiện"],"correct":2},{"text":"Quan hệ extend phù hợp trong trường hợp nào?","options":["Các chức năng thuộc phạm vi hệ thống","Vai trò bên ngoài tương tác với hệ thống","Chuỗi bước thành công thông thường","Bổ sung hành vi tùy theo điều kiện"],"correct":3},{"text":"Ranh giới hệ thống trong use case thể hiện gì?","options":["Các chức năng thuộc phạm vi hệ thống","Mục tiêu tương tác của tác nhân với hệ thống","Điều kiện cần đúng trước khi thực hiện","Nhánh xử lý hợp lệ khác luồng chính"],"correct":0}]},{"key":"systems-lab","order":5,"questions":[{"text":"Class diagram mức phân tích mô tả gì?","options":["Một hoặc nhiều đối tượng liên kết","Thành phần có thể tồn tại độc lập","Lớp nghiệp vụ cùng quan hệ của chúng","Dữ liệu trạng thái của đối tượng"],"correct":2},{"text":"Attribute của class là gì?","options":["Mối liên hệ giữa hai lớp","Quan hệ kế thừa giữa các lớp","Không, cần đánh giá vai trò nghiệp vụ","Dữ liệu trạng thái của đối tượng"],"correct":3},{"text":"Association dùng để biểu diễn điều gì?","options":["Mối liên hệ giữa hai lớp","Một hoặc nhiều đối tượng liên kết","Thành phần phụ thuộc vòng đời vào toàn thể","Giữ trọng tâm khái niệm nghiệp vụ"],"correct":0},{"text":"Multiplicity 1..* nghĩa là gì?","options":["Hành vi của đối tượng","Một hoặc nhiều đối tượng liên kết","Quan hệ kế thừa giữa các lớp","Thành phần có thể tồn tại độc lập"],"correct":1},{"text":"Generalization thể hiện gì?","options":["Không, cần đánh giá vai trò nghiệp vụ","Lớp nghiệp vụ cùng quan hệ của chúng","Quan hệ kế thừa giữa các lớp","Thành phần phụ thuộc vòng đời vào toàn thể"],"correct":2},{"text":"Composition biểu diễn quan hệ nào?","options":["Thành phần có thể tồn tại độc lập","Giữ trọng tâm khái niệm nghiệp vụ","Dữ liệu trạng thái của đối tượng","Thành phần phụ thuộc vòng đời vào toàn thể"],"correct":3},{"text":"Aggregation khác composition chủ yếu ở đâu?","options":["Thành phần có thể tồn tại độc lập","Không, cần đánh giá vai trò nghiệp vụ","Hành vi của đối tượng","Mối liên hệ giữa hai lớp"],"correct":0},{"text":"Một danh từ trong yêu cầu luôn là class?","options":["Một hoặc nhiều đối tượng liên kết","Không, cần đánh giá vai trò nghiệp vụ","Giữ trọng tâm khái niệm nghiệp vụ","Lớp nghiệp vụ cùng quan hệ của chúng"],"correct":1},{"text":"Vì sao tránh đưa chi tiết database vào mô hình phân tích?","options":["Dữ liệu trạng thái của đối tượng","Quan hệ kế thừa giữa các lớp","Giữ trọng tâm khái niệm nghiệp vụ","Hành vi của đối tượng"],"correct":2},{"text":"Phương thức trong class biểu diễn gì?","options":["Lớp nghiệp vụ cùng quan hệ của chúng","Mối liên hệ giữa hai lớp","Thành phần phụ thuộc vòng đời vào toàn thể","Hành vi của đối tượng"],"correct":3}]},{"key":"systems-lab","order":6,"questions":[{"text":"Tinh chế lớp nhằm mục đích gì?","options":["Tốc độ truy vấn trên cột được lập chỉ mục","Làm rõ thuộc tính và trách nhiệm của lớp","Định danh duy nhất một bản ghi","Dư thừa và bất nhất dữ liệu"],"correct":1},{"text":"Primary key có chức năng gì?","options":["Ngăn lưu giá trị rỗng ở cột bắt buộc","Nhóm thao tác thành đơn vị nhất quán","Định danh duy nhất một bản ghi","Tham chiếu bản ghi thuộc bảng liên quan"],"correct":2},{"text":"Foreign key dùng để làm gì?","options":["Dư thừa và bất nhất dữ liệu","Giá trị trong phạm vi ràng buộc không trùng","Quan hệ nhiều-nhiều","Tham chiếu bản ghi thuộc bảng liên quan"],"correct":3},{"text":"Chuẩn hóa dữ liệu giúp giảm điều gì?","options":["Dư thừa và bất nhất dữ liệu","Ngăn lưu giá trị rỗng ở cột bắt buộc","Tốc độ truy v