nên chia hướng dẫn thành nhiều bước ngắn?","options":["Người dùng trình đọc màn hình","Kiểm chứng khả năng tái hiện các bước","Giảm nhầm lẫn khi thực hành","Các bước thực hiện có thể kiểm chứng"],"correct":2}]},{"key":"word","order":7,"questions":[{"text":"Mục tiêu của bản đề xuất hoạt động nhóm là gì?","options":["Thuyết phục người xem phê duyệt kế hoạch","Mục tiêu, nguồn lực, tiến độ và kinh phí","Trách nhiệm trong công việc nhóm","Tóm tắt các ý quan trọng của đề xuất"],"correct":0},{"text":"Bản đề xuất nên có mục nào?","options":["Tên dự án và thông tin nhận diện","Mục tiêu, nguồn lực, tiến độ và kinh phí","Các mốc công việc theo thời gian","Hạng mục và chi phí ước tính"],"correct":1},{"text":"Timeline giúp thể hiện điều gì?","options":["Chứa dữ liệu bổ trợ cho nội dung chính","Tránh mâu thuẫn giữa các phần tài liệu","Các mốc công việc theo thời gian","Trách nhiệm trong công việc nhóm"],"correct":2},{"text":"RACI được dùng để làm rõ điều gì?","options":["Hạng mục và chi phí ước tính","Tóm tắt các ý quan trọng của đề xuất","Mức đáp ứng mục tiêu và tính khả thi","Trách nhiệm trong công việc nhóm"],"correct":3},{"text":"Ngân sách dự kiến cần kèm thông tin nào?","options":["Hạng mục và chi phí ước tính","Chứa dữ liệu bổ trợ cho nội dung chính","Tên dự án và thông tin nhận diện","Thuyết phục người xem phê duyệt kế hoạch"],"correct":0},{"text":"Phụ lục có vai trò gì?","options":["Mục tiêu, nguồn lực, tiến độ và kinh phí","Chứa dữ liệu bổ trợ cho nội dung chính","Tóm tắt các ý quan trọng của đề xuất","Tránh mâu thuẫn giữa các phần tài liệu"],"correct":1},{"text":"Executive summary là gì?","options":["Mức đáp ứng mục tiêu và tính khả thi","Các mốc công việc theo thời gian","Tóm tắt các ý quan trọng của đề xuất","Tên dự án và thông tin nhận diện"],"correct":2},{"text":"Trang bìa nên trình bày gì?","options":["Tránh mâu thuẫn giữa các phần tài liệu","Thuyết phục người xem phê duyệt kế hoạch","Trách nhiệm trong công việc nhóm","Tên dự án và thông tin nhận diện"],"correct":3},{"text":"Vì sao cần rà soát tính nhất quán của số liệu?","options":["Tránh mâu thuẫn giữa các phần tài liệu","Mức đáp ứng mục tiêu và tính khả thi","Mục tiêu, nguồn lực, tiến độ và kinh phí","Hạng mục và chi phí ước tính"],"correct":0},{"text":"Tiêu chí đánh giá đề xuất là gì?","options":["Chứa dữ liệu bổ trợ cho nội dung chính","Mức đáp ứng mục tiêu và tính khả thi","Thuyết phục người xem phê duyệt kế hoạch","Các mốc công việc theo thời gian"],"correct":1}]},{"key":"word","order":8,"questions":[{"text":"Review tab trong Word chứa công cụ nào?","options":["Chấp nhận một thay đổi đã theo dõi","So sánh khác biệt giữa hai tài liệu","Kiểm tra lại và phát hành bản đã duyệt","Track Changes và Comments"],"correct":3},{"text":"Accept Change dùng để làm gì?","options":["Chấp nhận một thay đổi đã theo dõi","Từ chối một thay đổi đã theo dõi","Giới hạn các hình thức chỉnh sửa","Nhận xét đã được xử lý xong"],"correct":0},{"text":"Reject Change dùng để làm gì?","options":["Xác định tệp chính thức được sử dụng","Từ chối một thay đổi đã theo dõi","So sánh khác biệt giữa hai tài liệu","Tránh thay đổi ngoài phạm vi được giao"],"correct":1},{"text":"Compare Documents hỗ trợ gì?","options":["Kiểm tra lại và phát hành bản đã duyệt","Có cơ sở đối chiếu nội dung thay đổi","So sánh khác biệt giữa hai tài liệu","Giới hạn các hình thức chỉnh sửa"],"correct":2},{"text":"Restrict Editing dùng để làm gì?","options":["Tránh thay đổi ngoài phạm vi được giao","Nhận xét đã được xử lý xong","Track Changes và Comments","Giới hạn các hình thức chỉnh sửa"],"correct":3},{"text":"Vì sao cần phân quyền người góp ý?","options":["Tránh thay đổi ngoài phạm vi được giao","Kiểm tra lại và phát hành bản đã duyệt","Xác định tệp chính thức được sử dụng","Chấp nhận một thay đổi đã theo dõi"],"correct":0},{"text":"Sau khi tổng hợp góp ý nên làm gì?","options":["Từ chối một thay đổi đã theo dõi","Kiểm tra lại và phát hành bản đã duyệt","Nhận xét đã được xử lý xong","Có cơ sở đối chiếu nội dung thay đổi"],"correct":1},{"text":"Khái niệm resolved comment là gì?","options":["Track Changes và Comments","So sánh khác biệt giữa hai tài liệu","Nhận xét đã được xử lý xong","Xác định tệp chính thức được sử dụng"],"correct":2},{"text":"Theo dõi phiên bản cuối giúp gì?","options":["Có cơ sở đối chiếu nội dung thay đổi","Chấp nhận một thay đổi đã theo dõi","Giới hạn các hình thức chỉnh sửa","Xác định tệp chính thức được sử dụng"],"correct":3},{"text":"Vì sao nên lưu bản gốc trước khi phản biện?","options":["Có cơ sở đối chiếu nội dung thay đổi","Track Changes và Comments","Từ chối một thay đổi đã theo dõi","Tránh thay đổi ngoài phạm vi được giao"],"correct":0}]}]$bank$::jsonb) LOOP
   SELECT cc.course_id INTO STRICT v_course FROM lms.curated_courses cc WHERE cc.course_key=s->>'key';
   SELECT l.lesson_id INTO STRICT v_lesson FROM lms.lessons l WHERE l.course_id=v_course
       AND l.lesson_order=(s->>'order')::int AND l.is_published AND NOT l.is_deleted;
   SELECT q.quiz_id INTO v_quiz FROM assessment.quizzes q WHERE q.lesson_id=v_lesson
       AND q.course_id=v_course AND q.is_published AND NOT q.is_deleted ORDER BY q.quiz_id DESC LIMIT 1;
   IF v_quiz IS NULL THEN
     INSERT INTO assessment.quizzes(course_id,lesson_id,title,description,time_limit_seconds,passing_score,max_attempts,is_published)
     VALUES(v_course,v_lesson,'Quiz cuối bài', '[VEDU-PATCH-HE-THONG-WORD-V1]',900,7,3,true)
     RETURNING quiz_id INTO v_quiz;
   END IF;
   SELECT COUNT(*) INTO v_num FROM assessment.questions WHERE quiz_id=v_quiz;
   IF v_num NOT IN (0,3,10) THEN RAISE EXCEPTION 'Unexpected quiz % question count %',v_quiz,v_num; END IF;
   SELECT COUNT(*) INTO v_attempts FROM assessment.quiz_attempts WHERE quiz_id=v_quiz;
   IF v_num=0 AND v_attempts>0 THEN RAISE EXCEPTION 'Quiz % has attempts but no questions',v_quiz; END IF;
   FOR i IN 1..10 LOOP
     item:=s->'questions'->(i-1);
     IF jsonb_array_length(item->'options')<>4 THEN RAISE EXCEPTION 'Invalid bank options % %',s->>'key',i; END IF;
     IF v_num=10 THEN
       CONTINUE; -- Keep previously completed quiz unchanged.
     ELSIF v_num=3 AND i<=3 THEN
       CONTINUE; -- Preserve all three existing questions/answers exactly as they are,
                 -- regardless of answer count or stored attempts.
     ELSE
       INSERT INTO assessment.questions(quiz_id,question_text,question_type,question_order,points)
       VALUES(v_quiz,item->>'text','SINGLE_CHOICE',i,1) RETURNING question_id INTO v_q;
       FOR j IN 1..4 LOOP
         INSERT INTO assessment.answers(question_id,answer_text,is_correct,answer_order)
         VALUES(v_q,item->'options'->>(j-1),((item->>'correct')::int=j-1),j);
       END LOOP;
     END IF;
   END LOOP;
   UPDATE assessment.quizzes SET time_limit_seconds=GREATEST(COALESCE(time_limit_seconds,0),900), updated_at=now() WHERE quiz_id=v_quiz;
   IF (SELECT COUNT(*) FROM assessment.questions WHERE quiz_id=v_quiz)<>10 THEN
     RAISE EXCEPTION 'Quiz % does not have exactly 10 questions',v_quiz;
   END IF;
 END LOOP;
END $patch$;
COMMIT;
